@media (max-width: 768px) {

    .nav-shell,
    body > footer .footer-shell {
        width: calc(100% - 1rem);
    }

    .page-shell {
        width: calc(100% - 1rem);
        margin-top: 0.75rem;
        padding-top: 0;
        padding-bottom: 1.5rem;
    }

    .quickstart-shell {
        width: 100%;
        padding: 0.92rem;
    }

    .quickstart-head {
        align-items: stretch;
    }

    .quickstart-toggle {
        width: 100%;
        justify-content: center;
    }

    .quickstart-steps {
        grid-template-columns: 1fr;
    }

    .section-shell {
        padding: 1.05rem;
    }

    .form-panel {
        padding: 0.85rem;
    }

    .page-intro-actions {
        width: 100%;
    }

    .page-intro-actions .btn-primary,
    .page-intro-actions .btn-ghost {
        flex: 1 1 auto;
        justify-content: center;
    }

    .chart-grid {
        grid-template-columns: 1fr;
    }

    .chart-card {
        min-height: 200px;
        padding: 0.8rem;
    }

    .chart-card canvas {
        height: 170px !important;
        max-height: 170px;
    }

    .metric-panels,
    .metric-panels-wide,
    .player-kpi-grid,
    .ruleset-stats,
    .ruleset-overview-grid {
        grid-template-columns: 1fr;
    }

    .ruleset-form-section .metric-row {
        align-items: center;
        min-height: 2.5rem;
    }

    .ruleset-form-section .metric-row input[type="checkbox"] {
        width: 1.1rem;
        height: 1.1rem;
        flex: 0 0 auto;
    }

    .ruleset-hero {
        padding: 0.85rem;
    }

    .nav-shell.nav-auth-page {
        display: flex !important;
        align-items: center;
        justify-content: space-between;
    }

    .nav-shell.nav-auth-page .nav-mobile-toggle,
    .nav-shell.nav-auth-page .nav-center {
        display: none !important;
    }

    .nav-shell.nav-auth-page .nav-right {
        display: flex !important;
        width: auto;
        margin-left: auto;
    }

    .nav-mobile-toggle {
        display: inline-flex;
        margin-left: 0;
        grid-column: 3;
        grid-row: 1;
        justify-self: end;
    }

    .nav-shell-auth .nav-center,
    .nav-shell-guest .nav-right {
        display: none !important;
        width: 100%;
    }

    .nav-shell.is-open .nav-center {
        display: grid !important;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        overflow-x: visible;
        gap: 0.42rem;
        justify-content: stretch;
        padding: 0.34rem 0.36rem !important;
    }

    .nav-shell.is-open .nav-center .nav-link {
        flex: initial;
        width: 100%;
        min-width: 0;
    }

    .nav-shell-auth {
        display: grid !important;
        grid-template-columns: minmax(0, 1fr) auto auto;
        align-items: center;
        column-gap: 0.5rem;
        row-gap: 0.55rem;
    }

    .nav-brand {
        gap: 0.55rem !important;
        max-width: calc(100% - 7.8rem);
    }

    .nav-brand .brand-title {
        max-width: 100%;
        overflow: hidden;
        text-overflow: ellipsis;
