@media (max-width: 900px) {
    .player-detail-overhaul {
        max-width: 100%;
        padding: 0.95rem;
    }

    .player-detail-overhaul .players-fusion-metrics {
        padding: 1rem 0.92rem;
    }

    .player-detail-overhaul .player-detail-hero {
        grid-template-columns: minmax(0, 1fr);
        padding: 1rem;
    }

    .player-detail-overhaul .player-profile-identity {
        width: 100%;
        gap: 0.8rem;
        padding: 0.7rem;
    }

    .player-detail-overhaul .player-profile-avatar-shell {
        width: 4.35rem;
        border-radius: 1.15rem;
    }

    .player-detail-overhaul .player-profile-avatar {
        border-radius: 0.92rem;
    }

    .player-detail-overhaul .players-fusion-head .ruleset-section-title {
        font-size: 1.3rem;
    }

    .player-detail-overhaul .players-fusion-head .ruleset-section-subtitle {
        font-size: 0.9rem;
        line-height: 1.56;
    }

    .player-detail-overhaul .player-detail-name {
        font-size: clamp(1.5rem, 7vw, 1.9rem);
    }

    .player-detail-overhaul .player-detail-meta__item {
        font-size: 0.75rem;
        padding: 0.28rem 0.56rem;
    }

    .player-detail-overhaul .player-detail-section {
        margin-top: 1rem;
    }

    .player-detail-overhaul .metric-domain-card {
        padding: 0.95rem;
    }

    .player-detail-overhaul .metric-domain-heading {
        align-items: flex-start;
    }

    .player-detail-overhaul .metric-domain-heading h3 {
        font-size: 1.02rem;
    }

    .player-detail-overhaul .metric-domain-intro {
        font-size: 0.87rem;
    }

    .player-detail-overhaul .player-stats-verdict {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-analysis-overview {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-analysis-grid {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-analysis-section-head {
        align-items: flex-start;
        flex-direction: column;
    }

    .player-detail-overhaul .player-stats-pillar-grid {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-metric-library__hero {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .chart-scroll-hint {
        font-size: 0.75rem;
        line-height: 1.38;
    }

    .player-detail-overhaul .chart-grid-feature .chart-card-feature {
        min-height: 346px;
        padding: 0.94rem;
    }

    .player-detail-overhaul .chart-grid-feature .chart-card-feature .chart-title {
        font-size: 1.06rem;
    }

    .player-detail-overhaul .chart-grid-feature .chart-card-feature .metric-line-chart {
        height: 282px;
    }

    .player-detail-overhaul .chart-grid-scroll .chart-card {
        flex-basis: min(620px, 96vw);
        min-height: 328px;
        padding: 0.88rem;
    }

    .player-detail-overhaul .chart-grid-scroll .chart-title {
        font-size: 1.01rem;
    }

    .player-detail-overhaul .chart-grid-scroll .metric-line-chart {
        height: 268px;
    }

    .player-detail-overhaul .chart-bar-insight {
        padding: 0.58rem 0.62rem;
    }

    .player-detail-overhaul .chart-bar-insight-row {
        grid-template-columns: 1fr;
        gap: 0.12rem;
        padding: 0.18rem 0;
    }

    .player-detail-overhaul .chart-bar-insight-key {
        font-size: 0.72rem;
    }

    .player-detail-overhaul .chart-bar-insight-value {
        font-size: 0.76rem;
    }
}

