@media (max-width: 560px) {
    .player-detail-overhaul .player-stats-hero {
        display: grid;
    }

    .player-detail-overhaul .player-stats-verdict {
        padding: 0.88rem;
    }

    .player-detail-overhaul .player-stats-verdict__signals {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-analysis-scorecard {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .player-detail-overhaul .player-analysis-scorecard>div:nth-child(odd) {
        border-left: 0;
    }

    .player-detail-overhaul .player-analysis-scorecard>div:nth-child(even) {
        border-left: 1px solid rgba(95, 146, 166, 0.18);
    }

    .player-detail-overhaul .player-analysis-chapter {
        padding: 0.78rem;
    }

    .player-detail-overhaul .player-analysis-card__takeaway {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-analysis-card__metrics>.player-analysis-card__metric {
        flex-basis: 100%;
    }

    .player-detail-overhaul .player-evidence-domain__mode {
        display: none;
    }

    .player-detail-overhaul .player-metric-library__totals {
        grid-template-columns: 1fr;
    }

    .player-detail-overhaul .player-metric-domain>summary {
        grid-template-columns: minmax(0, 1fr) auto;
    }

    .player-detail-overhaul .player-metric-domain>summary em {
        display: none;
    }

    .player-detail-overhaul .player-metric-card-grid,
    .player-detail-overhaul .player-metric-card-grid--columns-1,
    .player-detail-overhaul .player-metric-card-grid--columns-2,
    .player-detail-overhaul .player-metric-card-grid--columns-3 {
        padding: 0.58rem;
    }

    .player-detail-overhaul .player-metric-card-grid>.player-metric-card {
        flex-basis: 100%;
    }

    .player-detail-overhaul .player-metric-card-grid--coin-finance>.player-metric-card--coin-overview,
