    .player-detail-overhaul .player-metric-card-grid--donations>.player-metric-card--series,
    .player-detail-overhaul .player-metric-card-grid--gold>.player-metric-card--gold-overview,
    .player-detail-overhaul .player-metric-card-grid--gold>.player-metric-card--series {
