    .player-detail-overhaul .player-metric-card-grid--columns-3.player-metric-card-grid--gold>.player-metric-card:not(.player-metric-card--series):not(.player-metric-card--featured):not(.player-metric-card--meal-orders-primary):not(.player-metric-card--meal-orders-summary):not(.player-metric-card--gold-overview) {
