@media (max-width: 900px) {
    .happiness-score-desktop {
        display: none;
    }

    .happiness-score-mobile {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        align-items: stretch;
        gap: 0.85rem;
        margin-top: 0.75rem;
    }

    .happiness-score-mobile-card {
        min-width: 0;
        height: 100%;
        overflow: hidden;
        border: 2px solid var(--player-border);
        border-radius: 1rem;
        background: var(--player-surface);
    }

    .happiness-score-mobile-card--winner {
        box-shadow: inset 0 4px 0 #e0a626;
    }

    .happiness-score-mobile-player {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-items: center;
        gap: 0.75rem;
        min-width: 0;
        padding: 0.8rem;
    }

    .happiness-score-mobile-player img {
        width: 3rem;
        height: 3rem;
        border: 2px solid #fff;
        border-radius: 999px;
        object-fit: cover;
        box-shadow: 0 2px 8px rgba(34, 76, 105, 0.2);
    }

    .happiness-score-mobile-player>div {
        min-width: 0;
    }

    .happiness-score-mobile-player h3,
    .happiness-score-mobile-player p {
        margin: 0;
        overflow-wrap: anywhere;
    }

    .happiness-score-mobile-player h3 {
        color: #193e56;
        font-size: 1rem;
        font-weight: 850;
    }

    .happiness-score-mobile-player p {
        color: #647f90;
        font-size: 0.72rem;
        font-weight: 700;
    }

    .happiness-score-mobile-player .table-link {
        display: inline-block;
        max-width: 100%;
        margin-top: 0.2rem;
        white-space: normal;
        overflow-wrap: anywhere;
    }

    .happiness-score-mobile-card dl,
    .happiness-score-mobile-card dt,
    .happiness-score-mobile-card dd {
        margin: 0;
    }

    .happiness-score-mobile-row,
    .happiness-score-mobile-total {
        display: grid;
        grid-template-columns: minmax(0, 1fr) auto;
        align-items: center;
        gap: 0.65rem;
        min-width: 0;
        border-top: 1px solid #cbdce8;
        padding: 0.65rem 0.75rem;
    }

    .happiness-score-mobile-card .happiness-score-mobile-row {
        background: var(--player-surface);
    }

    .happiness-score-mobile-card .happiness-score-mobile-row:nth-child(even) {
        background: var(--player-surface-alt);
    }

    .happiness-score-mobile-card .happiness-score-value:not(.happiness-score-value--deduction) {
        background: var(--player-value);
        color: var(--player-ink);
    }

    .happiness-score-mobile-row dt {
        display: grid;
        grid-template-columns: 1.62rem minmax(0, 1fr);
        align-items: center;
        gap: 0.5rem;
        min-width: 0;
        color: #274c63;
        font-size: 0.8rem;
        font-weight: 750;
        line-height: 1.35;
    }

    .happiness-score-mobile-row dt>span:last-child {
        overflow-wrap: anywhere;
    }

    .happiness-score-mobile-row .happiness-score-number {
        margin-right: 0;
    }

    .happiness-score-mobile-total {
        background: var(--player-header);
        color: var(--player-ink);
        font-weight: 900;
    }

    .happiness-score-mobile-total dd {
        font-size: 1.05rem;
    }
}

