@media (prefers-reduced-motion: reduce) {

    .nav-dropdown[open] .nav-menu,
    .live-dot,
    .ruleset-modal-overlay,
    .ruleset-modal-container,
    .work-calendar-cell--mascot .mascot-icon,
    .work-calendar-cell.is-active-day::after,
    .work-calendar-cell--rest.is-active-day::after,
    .player-detail-overhaul .player-analysis-overview.is-visible::after,
    .auth-split-card.auth-mode-login .auth-split-right,
    .auth-split-card.auth-mode-register .auth-split-right,
    .auth-split-card.auth-switching-left .auth-split-right,
    .auth-split-card.auth-switching-right .auth-split-right {
        animation: none !important;
    }

    .player-detail-overhaul .player-stats-motion-ready [data-player-stats-reveal],
    .player-detail-overhaul .player-stats-motion-ready .player-analysis-overview[data-player-stats-reveal] .player-analysis-scorecard>div,
    .player-detail-overhaul .player-stats-motion-ready .player-stats-actions-section[data-player-stats-reveal] .player-stat-action,
    .player-detail-overhaul .player-stats-motion-ready .player-analysis-chapter[data-player-stats-reveal] .player-analysis-card {
        opacity: 1 !important;
        transform: none !important;
        transition: none !important;
    }

    .player-detail-overhaul .player-stat-action,
    .player-detail-overhaul .player-stat-action__signal,
    .player-detail-overhaul .player-analysis-scorecard>div,
    .player-detail-overhaul .player-analysis-card {
        transition: none !important;
    }

    .player-detail-overhaul .player-stat-action:hover,
    .player-detail-overhaul .player-stat-action:hover .player-stat-action__signal,
    .player-detail-overhaul .player-analysis-scorecard>div:hover,
    .player-detail-overhaul .player-analysis-card:hover {
        filter: none !important;
        transform: none !important;
    }
}

