@media (max-width: 768px) {
    .page-intro {
        align-items: flex-start;
    }

    .ruleset-quick-tools-controls {
        grid-template-columns: 1fr;
    }

    .ruleset-quick-reset {
        justify-self: start;
    }

    .ruleset-bulk-toolbar,
    .ruleset-pagination {
        justify-content: flex-start;
    }

    .ruleset-hero {
        grid-template-columns: 1fr;
    }

    .ruleset-hero-meta {
        align-items: flex-start;
    }

    .ruleset-detail-hero {
        grid-template-columns: 1fr;
        padding: 0.72rem;
    }

    .ruleset-detail-meta {
        justify-items: flex-start;
    }

    .ruleset-index-count {
        font-size: 1.35rem;
    }

    .ruleset-index-bulk-hint {
        width: 100%;
        order: 3;
    }

    .players-session-summary {
        align-items: flex-start;
    }

    .ruleset-layout-grid {
        grid-template-columns: 1fr;
    }

    .auth-split-card {
        grid-template-columns: 1fr;
        min-height: 0;
        border-radius: 1.5rem;
    }

    .auth-split-card.auth-mode-register .auth-split-right,
    .auth-split-card.auth-mode-register .auth-split-left {
        grid-column: auto;
    }

    .auth-split-left {
        padding: 2rem 1.2rem 1.4rem;
    }

    .auth-split-right {
        padding: 1.6rem 1.2rem 2rem;
    }
}

