@media (max-width: 640px) {
    .home-command-intro {
        min-height: 390px;
        padding: 1.35rem;
        border-radius: 1.5rem 1.5rem 0.7rem 1.5rem;
    }

    .home-command-badge {
        font-size: 0.67rem;
        letter-spacing: 0.14em;
    }

    .home-command-title {
        font-size: clamp(2.05rem, 11vw, 3.1rem);
    }

    .home-command-actions {
        width: 100%;
        gap: 0.58rem;
    }

    .home-command-actions .btn-primary,
    .home-command-actions .btn-ghost {
        width: 100%;
        justify-content: center;
    }

    .home-live-card {
        display: grid;
        min-height: 0;
        grid-template-columns: minmax(0, 1fr) auto;
        grid-template-areas: "live-header live-ring";
        align-items: center;
        justify-content: stretch;
        justify-items: start;
        gap: 0.65rem 1rem;
        padding: 1.2rem;
        border-radius: 1.5rem 1.5rem 1.5rem 0.7rem;
    }

    .home-live-header {
        grid-area: live-header;
    }

    .home-session-ring {
        grid-area: live-ring;
        width: 7.25rem;
    }

    .home-stat-grid {
        grid-template-columns: 1fr;
        gap: 0.75rem;
    }

    .home-stat-card {
        min-height: 118px;
        padding: 1rem 1.1rem;
        border-radius: 1.1rem;
    }

    .home-stat-accent {
        top: 1rem;
        right: 1rem;
    }

    .table-wrap table {
        min-width: 28rem;
        font-size: 0.82rem;
    }

    .table-wrap table.mobile-card-table {
        min-width: 0;
        width: 100%;
        border-collapse: separate;
        border-spacing: 0;
    }

    .table-wrap table.mobile-card-table.players-session-table {
        min-width: 0 !important;
        table-layout: auto !important;
    }

    .players-session-table colgroup {
        display: none;
    }

    .table-wrap table.mobile-card-table thead {
        display: none;
    }

    .table-wrap table.mobile-card-table tbody {
        display: grid;
        gap: 0.62rem;
    }

    .table-wrap table.mobile-card-table tbody tr {
        display: block;
        border: 1px solid #bde7e1;
        border-radius: 0.85rem;
        background: rgba(255, 255, 255, 0.92);
        padding: 0.36rem 0.4rem;
    }

    .table-wrap table.mobile-card-table tbody tr.border-t {
        border-top: 1px solid #bde7e1 !important;
    }

    .table-wrap table.mobile-card-table td {
        display: grid;
        grid-template-columns: minmax(7.2rem, 42%) 1fr;
        align-items: start;
        gap: 0.48rem;
        padding: 0.42rem 0.45rem !important;
        border: 0 !important;
        white-space: normal !important;
        overflow-wrap: anywhere !important;
        word-break: break-word;
        text-align: left !important;
    }

    .table-wrap table.mobile-card-table td::before {
        content: attr(data-label);
        color: #557688;
        font-size: 0.68rem;
        font-weight: 800;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        line-height: 1.25;
        text-align: left;
    }

    .table-wrap table.mobile-card-table td.players-session-player {
        grid-template-columns: 1fr;
        gap: 0.3rem;
    }

    .players-session-player>div {
        min-width: 0;
    }

    .players-session-player .font-medium {
        word-break: normal;
        overflow-wrap: anywhere;
    }

    .players-session-action .table-link {
        width: 100%;
    }

    .table-wrap table.mobile-card-table .mobile-card-empty {
        display: block;
        padding: 0.72rem !important;
        text-align: left !important;
    }

    .table-wrap table.mobile-card-table .mobile-card-empty::before {
        content: none;
    }

    .table-wrap th,
    .table-wrap td {
        padding: 0.58rem 0.62rem !important;
    }

    .score-info--aggregate {
        width: min(24rem, 100%);
    }

    .form-input {
        padding: 0.66rem 0.8rem;
        font-size: 0.88rem;
    }

    .btn-primary,
    .btn-ghost {
        min-height: 2.55rem;
    }

    .metric-value {
        text-align: left;
    }

    .ruleset-row-actions {
        justify-content: flex-start;
    }
}

