@media (max-width: 480px) {
    .quickstart-title {
        font-size: 1.1rem;
    }

    .quickstart-step {
        padding: 0.62rem 0.64rem;
    }

    .ruleset-section-title {
        font-size: 0.9rem;
    }

    .ruleset-section-subtitle {
        font-size: 0.77rem;
    }

    .nav-brand .brand-title {
        display: none;
    }

    .nav-shell-auth .nav-brand {
        max-width: 100%;
    }

    .nav-shell-auth .brand-mark {
        width: 2.85rem;
        min-width: 2.85rem;
    }

    .nav-pill.nav-right {
        -webkit-backdrop-filter: none;
        backdrop-filter: none;
    }

    .nav-right .nav-dropdown-profile .profile-menu {
        position: fixed;
        top: 4.75rem;
        right: 1rem;
        left: auto;
        width: auto;
        min-width: min(17rem, calc(100vw - 3rem));
        box-sizing: border-box;
        max-height: calc(100dvh - 6rem);
        overflow: auto;
    }

    .nav-shell.is-open .nav-center .nav-link {
        grid-column: 1 / -1;
    }

    .section-shell {
        padding: 0.88rem;
    }

    .table-wrap table {
        min-width: 24.5rem;
    }

    .alert {
        padding: 0.64rem 0.72rem;
        font-size: 0.82rem;
    }

    .form-label {
        letter-spacing: 0.08em;
    }

    .auth-split-shell {
        padding-inline: 0.2rem;
    }

    .auth-split-card {
        border-radius: 1.1rem;
    }

    .auth-heading,
    .auth-split-right h2,
    .auth-panel-brand-text {
        overflow-wrap: normal !important;
        word-break: normal;
        hyphens: none;
    }

    .auth-heading {
        font-size: clamp(1.65rem, 9vw, 2rem);
    }

    .auth-login-btn {
        min-height: 2.95rem;
        font-size: 1rem;
    }

    .auth-split-right h2 {
        font-size: clamp(1.5rem, 8vw, 2rem);
    }

    .auth-signup-cta {
        width: 100%;
        min-width: 0;
    }

    .rulebook-stream {
        padding: 0.7rem;
    }

    .rulebook-stream-item {
        padding: 0.62rem 0.66rem;
        border-radius: 0.8rem;
    }

    .rulebook-heading {
        font-size: 1rem;
    }

    .btn-compact,
    .session-journey-filter-btn,
    .nav-menu-item {
        min-height: 2.75rem !important;
    }

    .ruleset-modal-close {
        width: 2.75rem;
        height: 2.75rem;
    }

    .auth-password-toggle {
        width: 2.5rem;
        min-height: 2.5rem;
    }

    .auth-panel-lang-btn {
        min-height: 2.25rem;
    }
}

