.work-calendar-shell {
    margin-top: 1.5rem;
    border: 3px solid #1a8c82;
    border-radius: 1.25rem;
    background: radial-gradient(circle at 50% 50%, #fafffc, #edf9f6);
    padding: clamp(0.75rem, 1.5vw, 1.25rem);
    box-shadow: 0 16px 36px rgba(26, 140, 130, 0.15);
    font-family: "Baloo 2", "Inter", sans-serif;
    user-select: none;
}

