@media (max-width: 600px) {
    .work-calendar-shell {
        max-width: 100%;
        overflow: hidden;
        padding: 0.5rem;
    }

    .work-calendar-title-bar {
        align-items: flex-start;
        flex-direction: column;
        gap: 0.2rem;
        margin: -0.5rem -0.5rem 0.7rem;
        padding: 0.5rem 0.65rem;
    }

    .work-calendar-title-bar h3 {
        font-size: 0.9rem;
    }

    .work-calendar-title-bar .subtitle {
        font-size: 0.67rem;
        line-height: 1.25;
    }

    .work-calendar-headers,
    .work-calendar-grid {
        grid-template-columns: repeat(7, minmax(0, 1fr));
        min-width: 0;
    }

    .work-calendar-headers {
        gap: 0.15rem;
    }

    .work-calendar-header-day {
        font-size: clamp(0.46rem, 2.1vw, 0.58rem);
        letter-spacing: 0;
    }

    .work-calendar-grid {
        gap: 0.18rem;
    }

    .work-calendar-cell {
        min-width: 0;
        min-height: 0;
        padding: 0.1rem;
        border-width: 1px;
        border-radius: 0.38rem;
    }

    .work-calendar-cell__number {
        font-size: clamp(0.72rem, 3vw, 0.9rem);
    }

    .work-calendar-cell__label {
        display: none;
        /* Hide Peduli Donasi / Investasi Emas text in small cells on mobile */
    }

    .work-calendar-cell .charity-icon,
    .work-calendar-cell .gold-icon,
